; ============================================================================
; DISPLAY IOCS
; The LCD is two HD61202 controllers: left 50H..53H (cmd 50H, data 52H, status
; 55H? read 53H), right 54H..57H, and both at once 58H..5BH. Rows are pages
; 0..7, DSPLPTR is the hardware scroll offset (display start line command C0H
; + 8*n). LCDWK1: b0 16x16 kanji mode (2 text rows), b1 40-column mode, b2
; ..., b3 control-code font. Most routines call the P0-B0 hook entry first
; (CALL 00xxH: the user-vector check) and bracket the LCD access with
; LCDBUSY/LCDFREE (90BCH/90C4H) and CRSROFF (892BH). BSPCTR: display on/off (A
; b0) - command 3EH/3FH to both controllers.
; ============================================================================

;------------------------------------------------------------------------------
; 8123H - (00E5H) Display on / off (BSPCTR)
; A b0: command 3EH / 3FH to both controllers.
;------------------------------------------------------------------------------
BSPCTR_B6:
	call 00B8H                      ; 8123  cdb800
	and 01H                         ; 8126  e601
	or 3EH                          ; 8128  f63e
	call LCDRDY                     ; 812A  cd7f81
	out (P_LCD1C),a                 ; 812D  d350
	ret                             ; 812F  c9



;------------------------------------------------------------------------------
; 8130H - (0112H) Clear the screen (CLS)
; All 4 text rows and the status line; cursor home.
;------------------------------------------------------------------------------
