	push de                         ; 8134  d5
	push bc                         ; 8135  c5
	call CRSROFF                    ; 8136  cd2b89
	call LCDBUSY                    ; 8139  cdbc90
	ld c,50H                        ; 813C  0e50
	xor a                           ; 813E  af
	call LCDCOL                     ; 813F  cdfc81
	ld a,(DSPLPTR)                  ; 8142  3a5cf0
	ld d,a                          ; 8145  57
	ld e,04H                        ; 8146  1e04
L8148:
	call LCDPAGE                    ; 8148  cdf081
	xor a                           ; 814B  af
	ld b,40H                        ; 814C  0640
L814E:
