	out (52H),a                     ; 8151  d352
	djnz L814E                      ; 8153  10f9
	inc d                           ; 8155  14
	ld a,d                          ; 8156  7a
	dec e                           ; 8157  1d
	jr nz,L8148                     ; 8158  20ee
	ld e,04H                        ; 815A  1e04
	ld c,50H                        ; 815C  0e50
