;------------------------------------------------------------------------------
; 9E95H - (01D8H) COM IOCS dispatcher
; C = function, D = channel (0 COM:, 1 COM1:, 2 COM2:). The handler returns
; through COMRET (POP HL / RET). Hardware: TC8576 CPC (ports 20H..23H). Work:
; F12FH.. line parameters per channel (F131H/F134H b6 X-control), F13FH
; transfer flags, F140H..F147H receive ring buffer, F14EH b6 COM file / b7
; open, F14FH port 23H image (b5 RTS, b7 ...), F150H error bits, F151H b3 XOFF
; received, b7 break, F152H b3 XOFF sent, F156H timeout counter. Documented:
; 01 CWCOM 02 CRCOM 03 CSNDA 04 CRCVA 07 CRCV1 0E CSETHS 0F CRESHS 10 CWOUTS
; 11 CRCTRL 12 CWDEV 13 CRDEV 14 CESND 15 CERCV 16 CSBRK 17 CSRCVB 1B CCLRSB
; 1C CCLRRB. Used by B3b: 06 width, 0B end-of-line code, 0C zone, 1D PCONSOLE
; read, 18 terminators, 20H kanji code conversion (&J/&K).
;------------------------------------------------------------------------------
COM_B6:
	ex af,af'                       ; 9E95  08
	push hl                         ; 9E96  e5
	push hl                         ; 9E97  e5
	ld hl,COMRET                    ; 9E98  21ad9e
	ex (sp),hl                      ; 9E9B  e3
	push hl                         ; 9E9C  e5
	push bc                         ; 9E9D  c5
	ld b,00H                        ; 9E9E  0600
	ld hl,COMTAB                    ; 9EA0  21af9e
	add hl,bc                       ; 9EA3  09
	add hl,bc                       ; 9EA4  09
	ld a,(hl)                       ; 9EA5  7e
	inc hl                          ; 9EA6  23
	ld h,(hl)                       ; 9EA7  66
	ld l,a                          ; 9EA8  6f
	ex af,af'                       ; 9EA9  08
	pop bc                          ; 9EAA  c1
	ex (sp),hl                      ; 9EAB  e3
	ret                             ; 9EAC  c9



;------------------------------------------------------------------------------
; 9EADH - Common return of the COM IOCS functions
;------------------------------------------------------------------------------
COMRET:
	pop hl                          ; 9EAD  e1



