	call STRBUFHL                   ; AAA9  cd5eab
	ld c,07H                        ; AAAC  0e07
	call COM_B6                     ; AAAE  cd959e
	ld b,01H                        ; AAB1  0601
	push hl                         ; AAB3  e5
